controls.old:
def blocks(values):
    """Independent connected-components representation of an observation."""
    remaining, answer = set(range(len(values))), []
    while remaining:
        first = min(remaining)
        component = {i for i in remaining if values[i] == values[first]}
        answer.append(frozenset(component))
        remaining -= component
    return tuple(answer)

